409	    // Everything else (including the original tag) stays fixed; only the
410	    // version moves to another in-range integer. The record stays legal but
411	    // the authenticated content changed, so the result is exit 1 with BOTH the
412	    // correct key and a wrong key: a wrong key must not reclassify the legal
413	    // version number as corrupt input.
414	    let variants = [
415	        kv_record("2", KV_TAG_V1),                 // 1 -> 2
416	        kv_record("4294967295", KV_TAG_V1),        // 1 -> high endpoint
