418	        // Legal JSON whitespace around members and around the number must not
419	        // change the version's meaning: still a structural legal mismatch.
420	        format!(
421	            r#"{{ "format" : 1 , "algorithm" : "HMAC-SHA256" , "key_id" : "{KV_KID}" , "key_version" : 2 , "fields" : [ "{KV_FIELD}" ] , "tag" : "{KV_TAG_V1}" }}"#
422	        ),
