1330	    // exercise Chinese, a real newline, leading/trailing whitespace, embedded
1331	    // '=' (a=b=c), a repeated value and a trailing empty field.
1332	    let separated: &[&str] = &[
1333	        "--key", "00ff", "--key-id", "id", "--key-version", "1",
1334	        "--field", "世界",
