1336	        "--field", " a=b=c ",
1337	        "--field", "x",
1338	        "--field", "x",
1339	        "--field", "",
1340	    ];
1341	    let inline: &[&str] = &[
1342	        "--key=00ff", "--key-id=id", "--key-version=1",
1343	        "--field=世界",
1344	        "--field=\n换行 ",
1345	        "--field= a=b=c ",
1346	        "--field=x",
1347	        "--field=x",
1348	        "--field=",
1349	    ];
1350	    let mixed: &[&str] = &[
1351	        "--key=00ff", "--key-id", "id", "--key-version=1",
1352	        "--field", "世界",
1353	        "--field=\n换行 ",
1354	        "--field", " a=b=c ",
1355	        "--field=x",
1356	        "--field", "x",
1357	        "--field=",
1358	    ];
1359	    let (rec, raw) =
1360	        expect_equivalent_spellings("all-four-options", &[separated, inline, mixed]);
1361	
