1370	        rec.fields,
1371	        vec![
1372	            "世界".to_string(),
1373	            "\n换行 ".to_string(),
1374	            " a=b=c ".to_string(),
1375	            "x".to_string(),
1376	            "x".to_string(),
1377	            String::new(),
1378	        ]
1379	    );
1380	    // Mixing spellings neither reorders fields, merges the duplicate "x", nor
1381	    // drops the trailing empty field: all six survive in argv order.
1382	    assert_eq!(rec.fields.len(), 6);
1383	
1384	    // The whitespace and the embedded '=' survive on the wire untrimmed.
1385	    let text = String::from_utf8(raw).unwrap();
1386	    assert!(text.contains("\" a=b=c \""), "surrounding whitespace must be kept: {text}");
1387	
1388	    // The actual key feeds only the MAC; it is not a record value.
1389	    let mut strings = Vec::new();
1390	    rec.raw.strings(&mut strings);
1391	    assert!(
1392	        strings.iter().all(|s| s != "00ff"),
1393	        "the raw key must not appear as a record value: {strings:?}"
1394	    );
1395	}
